[CmdletBinding()] param([string]$PackagePath)
Set-StrictMode -Version Latest; $ErrorActionPreference='Stop'; $root=Split-Path -Parent $PSScriptRoot; $failed=$false
function Invoke-Gate([string]$name,[scriptblock]$action){try{$global:LASTEXITCODE=0;& $action;if($LASTEXITCODE -ne 0){throw "Command exited with code $LASTEXITCODE."};Write-Host "$name ........ PASS"}catch{Write-Host "$name ........ FAIL: $($_.Exception.Message)" -ForegroundColor Red;$script:failed=$true}}
$release=([IO.File]::ReadAllText((Join-Path $root 'release/release.json'), [Text.UTF8Encoding]::new($false))|ConvertFrom-Json).product.version; Write-Host "UrbanPlanToolbox v$release Release Preflight"
Invoke-Gate 'Release Metadata' {& "$PSScriptRoot/Sync-ReleaseMetadata.ps1" -Check};Invoke-Gate 'Release Notes' {& "$PSScriptRoot/Sync-ReleaseNotes.ps1" -Version $release -Check};Invoke-Gate 'Documentation' {& "$PSScriptRoot/Test-DocumentationConsistency.ps1"};Invoke-Gate 'Data Contracts' {& "$PSScriptRoot/Test-DataContractEvolution.ps1"};Invoke-Gate 'Dependencies' {& "$PSScriptRoot/Test-DependencyPolicy.ps1"};Invoke-Gate 'Workflow Authority' {& "$PSScriptRoot/Test-WorkflowReleaseAuthority.ps1"};Invoke-Gate 'Tests' {dotnet test "$root/UrbanPlanToolbox.slnx" -c Release -p:Platform=x64 --no-restore};Invoke-Gate 'Debug Build' {dotnet build "$root/UrbanPlanToolbox.slnx" -c Debug -p:Platform=x64 --no-restore};Invoke-Gate 'Release Build' {dotnet build "$root/UrbanPlanToolbox.slnx" -c Release -p:Platform=x64 --no-restore};if($PackagePath){Invoke-Gate 'Static Package' {& "$PSScriptRoot/Test-AcceptancePackage.ps1" -PackagePath $PackagePath};Invoke-Gate 'Package Budget' {& "$PSScriptRoot/Test-PackageBudget.ps1" -PackagePath $PackagePath}}
if($failed){Write-Host 'RELEASE BLOCKED' -ForegroundColor Red;exit 1};Write-Host 'RELEASE READY'
